function contarIslas(mapa) {
  let islas = 0;
  const F = mapa.length, C = F ? mapa[0].length : 0;
  for (let f = 0; f < F; f++) {
    for (let c = 0; c < C; c++) {
      if (mapa[f][c] !== '1') continue;
      islas++;
      const pila = [[f, c]];
      mapa[f][c] = '0';
      while (pila.length) {
        const [y, x] = pila.pop();
        for (const [dy, dx] of [[1,0],[-1,0],[0,1],[0,-1]]) {
          const ny = y + dy, nx = x + dx;
          if (ny >= 0 && ny < F && nx >= 0 && nx < C && mapa[ny][nx] === '1') {
            mapa[ny][nx] = '0';
            pila.push([ny, nx]);
          }
        }
      }
    }
  }
  return islas;
}

solution.python:
def contarIslas(mapa):
    islas = 0
    F = len(mapa)
    C = len(mapa[0]) if F else 0
    for f in range(F):
        for c in range(C):
            if mapa[f][c] != '1':
                continue
            islas += 1
            pila = [(f, c)]
            mapa[f][c] = '0'
            while pila:
                y, x = pila.pop()
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < F and 0 <= nx < C and mapa[ny][nx] == '1':
                        mapa[ny][nx] = '0'
                        pila.append((ny, nx))
    return islas
